<script setup>
import {ref,computed,watch,inject,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import SubjectMetrics from '../components/SubjectMetrics.vue'
import {createMetricSubjects} from '../services/metric-subjects'
import DefinitionDialog from '../components/DefinitionDialog.vue'
import MetricDetailDialog from '../components/MetricDetailDialog.vue'
import {createMetricQuery,collectDueMetrics} from '../services/metric-query'
const repo=inject('repository'),route=useRoute(),router=useRouter(),domain=ref(),loading=ref(true),error=ref(''),revision=ref(0),updated=ref(new Date()),goal=ref('quality'),search=ref(''),status=ref('all'),selected=ref(),configOpen=ref(false),detailOpen=ref(false),base=ref({})
const fresh=()=>({time:'today',dept:'all',groups:[],surgery:{category:'all',subTypes:[]},levels:{levels:[]},start:'',end:''}),f=ref(fresh())
const subject=ref('team')
const subjects=computed(()=>domain.value?createMetricSubjects(domain.value):null)
const configMode=computed(()=>route.path.endsWith('/config'))
const timeOptions=[['today','当日'],['yesterday','昨日'],['this-week','本周'],['last-week','上周'],['this-month','本月'],['last-month','上月'],['this-year','本年'],['last-year','去年'],['custom','自定义日期']].map(([value,title])=>({value,title}))
const levelOptions=['一级手术','二级手术','三级手术','四级手术'].map((title,i)=>({value:'level'+(i+1),title}))
const groupOptions=computed(()=>!domain.value?[]:f.value.dept==='all'?Object.values(domain.value.departments).flat():domain.value.departments[f.value.dept]||[])
const typeOptions=computed(()=>!domain.value?[]:f.value.surgery.category==='all'?[]:domain.value.surgeryTypes[f.value.surgery.category]||[])
watch(()=>f.value.dept,()=>f.value.groups=f.value.groups.filter(g=>groupOptions.value.includes(g)))
watch(()=>f.value.surgery.category,()=>f.value.surgery.subTypes=[])
const invalidRange=computed(()=>f.value.time==='custom'&&(!f.value.start||!f.value.end||f.value.start>f.value.end))
function snapshot(){return {...JSON.parse(JSON.stringify(f.value)),time:f.value.time==='custom'?`custom:${f.value.start}:${f.value.end}`:f.value.time}}
const metrics=computed(()=>{revision.value;if(!domain.value||invalidRange.value)return [];const q=createMetricQuery(domain.value,snapshot());return domain.value.metrics.filter(m=>subjects.value.owner(m.id)==='team').map(m=>q(m.id)).filter(m=>m.value!==null)})
const counts=computed(()=>Object.fromEntries(['quality','efficiency','mdt'].map(g=>[g,metrics.value.filter(m=>m.decisionGoal===g).length])))
const rows=computed(()=>{
 revision.value
 const query=String(search.value||'').trim().toLowerCase()
 if(configMode.value)return domain.value?.metrics.filter(m=>[m.name,m.id,domain.value.categories[m.category]].join(' ').toLowerCase().includes(query))||[]
 return metrics.value.filter(m=>m.decisionGoal===goal.value&&(status.value==='all'||m.status===status.value)&&m.name.toLowerCase().includes(query))
})
async function load(){loading.value=true;try{domain.value=await repo.getDomain();error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
function select(m){selected.value=domain.value.metrics.find(d=>d.id===m.id);if(configMode.value)configOpen.value=true;else{base.value=snapshot();detailOpen.value=true}}
async function configure(id){detailOpen.value=false;await router.push('/metrics/config');selected.value=domain.value.metrics.find(m=>m.id===id);configOpen.value=true}
function saved(id){revision.value++;updated.value=new Date();if(id)last.set(id,Date.now())}
function reset(){f.value=fresh();search.value='';status.value='all'}
let timer,last=new Map()
onMounted(async()=>{await load();if(domain.value)collectDueMetrics(domain.value.metrics,id=>domain.value.config.get('metric',id).frequency,last,Date.now());timer=setInterval(()=>{if(configOpen.value||detailOpen.value||configMode.value||!domain.value)return;if(collectDueMetrics(domain.value.metrics,id=>domain.value.config.get('metric',id).frequency,last,Date.now()).length)saved()},15000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="page-heading"><div><h1>{{configMode?'指标配置':'指标监控'}}</h1><p>{{configMode?'维护指标分类、刷新频次与阈值，查看发布公式及来源。':'按统计主体分类查看指标，各主体独立筛选并查看趋势。'}}</p></div><VChip color="primary" variant="tonal" label>确定性演示数据</VChip></div><VAlert v-if="error" type="error">{{error}}<VBtn @click="load">重试</VBtn></VAlert><VProgressLinear v-if="loading" indeterminate/>
<template v-if="domain"><div v-if="!configMode" class="subject-tabs"><button v-for="(item,key) in subjects.subjects" :key="key" :class="{selected:subject===key}" @click="subject=key"><span>统计主体</span><strong>{{item.name}}</strong><span>{{subjects.definitions(key).length}} 项指标</span></button></div><template v-for="(item,key) in subjects.subjects" :key="key"><SubjectMetrics v-if="key!=='team'" v-show="!configMode&&subject===key" :subject="key" :subjects="subjects" :domain="domain"/></template><div v-show="configMode||subject==='team'"><VCard v-if="!configMode" class="mb-6"><div class="toolbar"><strong>统计范围</strong><VBtn variant="text" color="secondary" prepend-icon="tabler-refresh" @click="reset">重置全部筛选</VBtn></div><div class="filters"><div class="filter-field"><label>时间范围（场景日期）</label><VSelect v-model="f.time" :items="timeOptions"/></div><div class="filter-field"><label>科室</label><VSelect v-model="f.dept" :items="[{value:'all',title:'全部科室'},...Object.keys(domain.departments).map(g=>({value:g,title:g}))]"/></div><div class="filter-field"><label>医疗组</label><VSelect v-model="f.groups" :items="groupOptions" multiple chips closable-chips placeholder="全部医疗组" clearable/><div class="caption muted">空选代表全部</div></div><div class="filter-field"><label>手术等级</label><VSelect v-model="f.levels.levels" :items="levelOptions" multiple chips closable-chips placeholder="全部手术等级" clearable/></div><div class="filter-field"><label>一级术类</label><VSelect v-model="f.surgery.category" :items="[{value:'all',title:'全部术类'},...Object.keys(domain.surgeryTypes).map(g=>({value:g,title:g}))]"/></div><div class="filter-field"><label>具体术种</label><VSelect v-model="f.surgery.subTypes" :items="typeOptions" :disabled="f.surgery.category==='all'" multiple chips closable-chips placeholder="全部术种" clearable/></div><template v-if="f.time==='custom'"><div class="filter-field"><label>开始日期</label><VTextField type="date" v-model="f.start" :max="f.end||undefined"/></div><div class="filter-field"><label>结束日期</label><VTextField type="date" v-model="f.end" :min="f.start||undefined"/></div></template></div><VAlert v-if="invalidRange" type="warning" variant="tonal" class="mx-6 mb-6">请选择完整且开始不晚于结束的日期范围。</VAlert></VCard>
<div v-if="!configMode" class="workbench-tabs"><button v-for="(item,key) in domain.goals" :key="key" :class="{selected:goal===key}" @click="goal=key"><strong>{{item.label}}</strong><span>{{counts[key]}} 项指标</span></button></div>
<VCard class="mb-6"><div class="toolbar"><VTextField v-model="search" class="toolbar-search" prepend-inner-icon="tabler-search" :placeholder="configMode?'搜索名称、编号或分类':'搜索指标名称'" clearable aria-label="搜索指标"/><VSelect v-if="!configMode" v-model="status" :items="[{value:'all',title:'全部状态'},{value:'normal',title:'正常'},{value:'warning',title:'预警'},{value:'danger',title:'异常'}]" style="max-width:170px"/><span class="caption muted">{{rows.length}} 项{{configMode?'发布定义':'匹配指标'}}</span></div></VCard>
<div class="catalog-grid"><VCard v-for="m in rows" :key="m.id" class="definition-card" tabindex="0" role="button" :aria-label="(configMode?'配置':'查看趋势')+m.name" @click="select(m)" @keydown.enter="select(m)" @keydown.space.prevent="select(m)"><VCardText><div class="card-kicker"><span>{{domain.categories[m.category]}}</span><VChip v-if="!configMode" :color="{normal:'success',warning:'warning',danger:'error'}[m.status]" size="small" variant="tonal" label>{{{normal:'正常',warning:'预警',danger:'异常'}[m.status]}}</VChip></div><h2>{{m.name}}</h2><div v-if="!configMode" class="metric-value">{{m.value}}<small>{{m.unit}}</small></div><p class="definition-desc">{{m.desc}}</p><div class="card-end"><code v-if="configMode">{{m.id}}</code><span v-else class="muted">{{domain.dateRange(snapshot().time).start}} ~ {{domain.dateRange(snapshot().time).end}}</span><span>{{configMode?'查看配置':'历史趋势'}} <VIcon icon="tabler-chevron-right" size="16"/></span></div></VCardText></VCard></div><VCard v-if="!rows.length" class="empty"><h3>当前范围没有匹配指标</h3><p>请调整统计范围、指标名称或状态。</p><VBtn variant="text" @click="search='';status='all'">清除名称与状态筛选</VBtn></VCard><p class="caption muted mt-5">{{configMode?'公式与来源随代码发布，仅开放分类、刷新频次和阈值参数。':`场景日期 ${domain.scenario.meta.date} · 最近刷新 ${updated.toLocaleTimeString('zh-CN',{hour12:false})} · 数值为演示算法，不代表正式国考发布口径。`}}</p>
<DefinitionDialog v-model="configOpen" kind="metric" :definition="selected" :domain="domain" @saved="saved"/><MetricDetailDialog v-model="detailOpen" :definition="selected" :domain="domain" :base="base" @configure="configure"/></div></template></template>
<style scoped>.subject-tabs{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:12px;margin-bottom:24px}.subject-tabs button{display:flex;flex-direction:column;gap:10px;text-align:start;padding:18px;background:rgb(var(--v-theme-surface));border:1px solid rgba(var(--v-border-color),var(--v-border-opacity));border-radius:6px;color:inherit}.subject-tabs .selected{border-color:rgb(var(--v-theme-primary));background:rgba(var(--v-theme-primary),.08)}.subject-tabs strong{font-size:18px}.subject-tabs span{font-size:12px;color:rgba(var(--v-theme-on-surface),.65)}@media(max-width:1100px){.subject-tabs{grid-template-columns:repeat(4,1fr)}}.workbench-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}.workbench-tabs button{border:1px solid rgba(var(--v-border-color),var(--v-border-opacity));border-radius:6px;text-align:start;padding:18px 20px;background:rgb(var(--v-theme-surface));color:inherit;display:flex;justify-content:space-between;gap:10px}.workbench-tabs strong{font-size:16px;font-weight:600}.workbench-tabs span{font-size:12px;color:rgba(var(--v-theme-on-surface),.6)}.workbench-tabs .selected{border-color:rgb(var(--v-theme-primary));background:rgba(var(--v-theme-primary),.07)}@media(max-width:800px){.workbench-tabs{grid-template-columns:1fr}}</style>
